//! Candidate-local native Rust witness for WP-RMT-002 State Machine.
#[derive(Debug,Clone,PartialEq,Eq)]pub struct TransitionDecision{pub accepted:bool,pub next_state:Option<&'static str>,pub guard_ids:Vec<&'static str>,pub effect_intents:Vec<&'static str>}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct StateMachineObservation{pub observed_transition_ids:Vec<&'static str>,pub observed_initial_state:&'static str,pub observed_terminal_states:Vec<&'static str>,pub observed_cycle_policy:&'static str,pub illegal_transition_observed:bool,pub guard_bypass_observed:bool,pub nondeterministic_outcome_observed:bool,pub effects_performed_inline:Vec<&'static str>,pub undeclared_cycle_observed:bool,pub invalid_transition_accepted:bool,pub hidden_mutation_observed:bool,pub stable_transition_ids:bool}
pub const TRANSITION_IDS:[&str;2]=["sm.pending.confirm.settled/v1","sm.pending.reject.failed/v1"];
pub fn transition(state:&str,trigger:&str,guard_passed:bool)->TransitionDecision{if !guard_passed{return TransitionDecision{accepted:false,next_state:None,guard_ids:vec![],effect_intents:vec![]}}match(state,trigger){("pending","confirm")=>TransitionDecision{accepted:true,next_state:Some("settled"),guard_ids:vec!["can-settle"],effect_intents:vec!["persist-settlement","append-settlement-created"]},("pending","reject")=>TransitionDecision{accepted:true,next_state:Some("failed"),guard_ids:vec!["can-settle"],effect_intents:vec!["record-rejection"]},_=>TransitionDecision{accepted:false,next_state:None,guard_ids:vec![],effect_intents:vec![]}}}
pub fn baseline()->StateMachineObservation{StateMachineObservation{observed_transition_ids:TRANSITION_IDS.to_vec(),observed_initial_state:"pending",observed_terminal_states:vec!["settled","failed"],observed_cycle_policy:"declared-only",illegal_transition_observed:false,guard_bypass_observed:false,nondeterministic_outcome_observed:false,effects_performed_inline:vec![],undeclared_cycle_observed:false,invalid_transition_accepted:false,hidden_mutation_observed:false,stable_transition_ids:true}}
pub fn evaluate(o:&StateMachineObservation)->Vec<&'static str>{let mut f=Vec::new();let mut actual=o.observed_transition_ids.clone();actual.sort();let mut expected=TRANSITION_IDS.to_vec();expected.sort();if o.illegal_transition_observed||actual!=expected{f.push("RMT_SM_ILLEGAL_TRANSITION");}if o.observed_initial_state!="pending"{f.push("RMT_SM_INITIAL_STATE_DRIFT");}let mut terminals=o.observed_terminal_states.clone();terminals.sort();if terminals!=vec!["failed","settled"]{f.push("RMT_SM_TERMINAL_STATE_DRIFT");}if o.guard_bypass_observed{f.push("RMT_SM_GUARD_BYPASS");}if o.nondeterministic_outcome_observed{f.push("RMT_SM_NONDETERMINISTIC_TRANSITION");}if !o.effects_performed_inline.is_empty(){f.push("RMT_SM_EXECUTES_EFFECT");}if o.observed_cycle_policy!="declared-only"||o.undeclared_cycle_observed{f.push("RMT_SM_CYCLE_POLICY_MISMATCH");}if o.invalid_transition_accepted{f.push("RMT_SM_INVALID_TRANSITION_SUCCESS");}if o.hidden_mutation_observed{f.push("RMT_SM_HIDDEN_MUTATION");}if !o.stable_transition_ids{f.push("RMT_SM_UNSTABLE_TRANSITION_IDENTITY");}f}
pub fn decode_effect_intent(keys:&[&str])->Result<(),&'static str>{let mut actual=keys.to_vec();actual.sort();if actual!=vec!["effect_intent_id","payload"]{return Err("RMT_S1_CLOSED_DECODE_UNKNOWN_MEMBER")}Ok(())}
